import networkx as nx
import json
import os
import pandas as pd
from typing import Dict, List


def search_algorithm(src, dsts, G, num_partitions):
    """Broadcast src to all dsts via a marginal-gain relay heuristic.

    Different from order-based greedy Steiner: at each step we compute,
    for every unserved destination, its cheapest route where edges already
    purchased by the tree cost 0, and commit the route minimizing marginal
    cost per newly served destination. Destinations lying on a committed
    route are served for free, so trunks are reused maximally. A plain
    shortest-path-union fallback is kept and the cheaper edge set wins."""
    h = G.copy()
    h.remove_edges_from(list(h.in_edges(src)) + list(nx.selfloop_edges(h)))

    bc_topology = BroadCastTopology(src, dsts, num_partitions)
    terminals = set(d for d in dsts if d != src)

    def prune(edges):
        """Iteratively drop edges to leaves that are not destinations."""
        edges = set(edges)
        changed = True
        while changed:
            changed = False
            out_deg, in_deg = {}, {}
            for s, t in edges:
                out_deg[s] = out_deg.get(s, 0) + 1
                in_deg[t] = in_deg.get(t, 0) + 1
            for s in list(out_deg):
                if s != src and s not in terminals and s not in in_deg:
                    edges = {e for e in edges if e[0] != s}
                    changed = True
        return edges

    def tree_cost(edges):
        return sum(G[s][t].get("cost") or 0 for s, t in edges)

    def build_gain_tree():
        """Marginal-gain relay: repeatedly buy the route that serves
        unserved destinations at the lowest cost-per-destination, with
        already-bought edges priced at zero."""
        paid = set()
        served = set()
        while len(served) < len(terminals):
            def wfun(u, v, e):
                return 0.0 if (u, v) in paid else (e.get("cost") or 0)
            best = None  # (ratio, marginal_cost, path, new_served)
            for d in terminals - served:
                try:
                    _, path = nx.single_source_dijkstra(h, src, d, weight=wfun)
                except Exception:
                    continue
                new_edges = {(path[i], path[i + 1])
                             for i in range(len(path) - 1)}
                marginal = sum(G[s][t].get("cost") or 0
                               for s, t in new_edges - paid)
                # destinations served for free along this path
                on_path = {p for p in path} & (terminals - served)
                gained = max(1, len(on_path))
                ratio = marginal / gained
                if best is None or ratio < best[0]:
                    best = (ratio, marginal, path, on_path)
            if best is None:
                # unreachable in pruned graph: fall back to raw shortest paths
                for d in terminals - served:
                    try:
                        path = nx.dijkstra_path(h, src, d, weight="cost")
                    except Exception:
                        path = nx.dijkstra_path(G, src, d, weight="cost")
                    for i in range(len(path) - 1):
                        paid.add((path[i], path[i + 1]))
                    served.add(d)
                break
            path = best[2]
            for i in range(len(path) - 1):
                paid.add((path[i], path[i + 1]))
            served |= set(path) & terminals
        return prune(paid)

    candidates = [build_gain_tree()]

    # Fallback: independent shortest paths, in case the tree misses a dst
    fallback_edges = set()
    for d in terminals:
        try:
            path = nx.dijkstra_path(h, src, d, weight="cost")
        except Exception:
            path = nx.dijkstra_path(G, src, d, weight="cost")
        for i in range(len(path) - 1):
            fallback_edges.add((path[i], path[i + 1]))
    candidates.append(prune(fallback_edges))

    tree_edges = min(candidates, key=tree_cost)

    # --- Emit per-partition paths along the shared tree ---
    tree = h.copy()
    tree.remove_edges_from(
        [e for e in list(tree.edges) if e not in tree_edges])
    tree.add_edges_from(
        [(s, t, dict(G[s][t])) for (s, t) in tree_edges if not tree.has_edge(s, t)])

    for dst in dsts:
        if dst == src:
            continue
        if dst in tree and nx.has_path(tree, src, dst):
            path = nx.dijkstra_path(tree, src, dst, weight="cost")
            edges = [[path[i], path[i + 1], G[path[i]][path[i + 1]]]
                     for i in range(len(path) - 1)]
        else:
            try:
                path = nx.dijkstra_path(h, src, dst, weight="cost")
            except Exception:
                path = nx.dijkstra_path(G, src, dst, weight="cost")
            edges = [[path[i], path[i + 1], G[path[i]][path[i + 1]]]
                     for i in range(len(path) - 1)]
        for j in range(num_partitions):
            for e in edges:
                bc_topology.append_dst_partition_path(dst, j, e)

    return bc_topology


class SingleDstPath(Dict):
    partition: int
    edges: List[List]  # [[src, dst, edge data]]


class BroadCastTopology:
    def __init__(self, src: str, dsts: List[str], num_partitions: int = 4, paths: Dict[str, SingleDstPath] = None):
        self.src = src  # single str
        self.dsts = dsts  # list of strs
        self.num_partitions = num_partitions

        # dict(dst) --> dict(partition) --> list(nx.edges)
        # example: {dst1: {partition1: [src->node1, node1->dst1], partition 2: [src->dst1]}}
        if paths is not None:
            self.paths = paths
            self.set_graph()
        else:
            self.paths = {dst: {str(i): None for i in range(num_partitions)} for dst in dsts}

    def get_paths(self):
        print(f"now the set path is: {self.paths}")
        return self.paths

    def set_num_partitions(self, num_partitions: int):
        self.num_partitions = num_partitions

    def set_dst_partition_paths(self, dst: str, partition: int, paths: List[List]):
        """
        Set paths for partition = partition to reach dst
        """
        partition = str(partition)
        self.paths[dst][partition] = paths

    def append_dst_partition_path(self, dst: str, partition: int, path: List):
        """
        Append path for partition = partition to reach dst
        """
        partition = str(partition)
        if self.paths[dst][partition] is None:
            self.paths[dst][partition] = []
        self.paths[dst][partition].append(path)

def make_nx_graph(cost_path=None, throughput_path=None, num_vms=1):
    """
    Default graph with capacity constraints and cost info
    nodes: regions, edges: links
    per edge:
        throughput: max tput achievable (gbps)
        cost: $/GB
        flow: actual flow (gbps), must be < throughput, default = 0
    """
    # Use relative path from this file's location
    current_dir = os.path.dirname(os.path.abspath(__file__))

    if cost_path is None:
        cost = pd.read_csv(os.path.join(current_dir, "profiles/cost.csv"))
    else:
        cost = pd.read_csv(cost_path)

    if throughput_path is None:
        throughput = pd.read_csv(os.path.join(current_dir, "profiles/throughput.csv"))
    else:
        throughput = pd.read_csv(throughput_path)

    G = nx.DiGraph()
    for _, row in throughput.iterrows():
        if row["src_region"] == row["dst_region"]:
            continue
        G.add_edge(row["src_region"], row["dst_region"], cost=None, throughput=num_vms * row["throughput_sent"] / 1e9)

    for _, row in cost.iterrows():
        if row["src"] in G and row["dest"] in G[row["src"]]:
            G[row["src"]][row["dest"]]["cost"] = row["cost"]

    # some pairs not in the cost grid
    no_cost_pairs = []
    for edge in G.edges.data():
        src, dst = edge[0], edge[1]
        if edge[-1]["cost"] is None:
            no_cost_pairs.append((src, dst))
    print("Unable to get costs for: ", no_cost_pairs)

    return G


# EVOLVE-BLOCK-END

# Helper functions that won't be evolved
def create_broadcast_topology(src: str, dsts: List[str], num_partitions: int = 4):
    """Create a broadcast topology instance"""
    return BroadCastTopology(src, dsts, num_partitions)

def run_search_algorithm(src: str, dsts: List[str], G, num_partitions: int):
    """Run the search algorithm and return the topology"""
    return search_algorithm(src, dsts, G, num_partitions)

